请对以下 case 进行三维加权评分。

=== case_id ===
Case-20-notif-aggregate-017

=== 用户原始指令 (query.txt) ===
分组通知卡用分隔线分几个区,上面天气+导航,下面可滚动待办列表,环形数据焦点,纯文字色块不要图片,运动紧迫感渐变

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "分组通知卡用分隔线分几个区,上面天气+导航,下面可滚动待办列表,环形数据焦点,纯文字色块不要图片,运动紧迫感渐变",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "StartNavigate",
        "params": {
          "dstLocation": {
            "latitude": "31.2304",
            "longitude": "121.4737"
          },
          "trafficpe": "Drive"
        }
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询区县名称",
            "sampleValue": "浦东新区"
          },
          "prefectureName": {
            "type": "string",
            "description": "天气查询城市名称",
            "sampleValue": "上海市"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          },
          "humidityPercent": {
            "type": "number",
            "description": "当前相对湿度百分比，用于环形数据焦点",
            "sampleValue": 68
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级",
            "sampleValue": "良"
          }
        }
      }
    },
    "navigation": {
      "destinationName": {
        "type": "string",
        "description": "导航目的地短名称",
        "sampleValue": "公司"
      },
      "etaText": {
        "type": "string",
        "description": "到达目的地预计耗时",
        "sampleValue": "22分"
      }
    },
    "todos": {
      "type": "array",
      "description": "待办通知列表，按紧急程度排序",
      "sampleValue": [
        {
          "priority": "急",
          "title": "16:00 提交周报"
        },
        {
          "priority": "会",
          "title": "18:30 训练打卡"
        },
        {
          "priority": "买",
          "title": "补充能量胶"
        }
      ],
      "items": {
        "type": "object",
        "properties": {
          "priority": {
            "type": "string",
            "description": "待办优先级或类别短标",
            "sampleValue": "急"
          },
          "title": {
            "type": "string",
            "description": "待办事项标题",
            "sampleValue": "16:00 提交周报"
          }
        }
      }
    }
  },
  "assetCandidates": []
}

